from pathlib import Path
from urllib.parse import unquote
import hashlib,json,re,subprocess
root=Path('/home/yu/projects/dsh-agent-team')
w=root/'.scratch/active/agent-tools-context-rendering'
new=[w/'README.md',w/'spec.md',w/'SCOPE.md',w/'materials/2026-10-29-implementation-notes.md',w/'materials/2026-10-29-accepted-flows.md',w/'materials/2026-10-29-superseded-tickets/README.md',*sorted((w/'issues').glob('*.md'))]
errors=[]; links=0
for p in new:
    text=p.read_text()
    if not text.endswith('\n') or text.endswith('\n\n'): errors.append(f'{p.name}: trailing newline')
    for num,line in enumerate(text.splitlines(),1):
        if line.rstrip()!=line: errors.append(f'{p.name}:{num}: trailing spaces')
    for url in re.findall(r'\]\(([^)]+)\)',text):
        if re.match(r'[a-z]+://',url): continue
        path,_,frag=url.partition('#'); target=(p.parent/unquote(path)).resolve() if path else p
        links+=1
        if not target.exists(): errors.append(f'{p.name}: missing {url}'); continue
        if frag and target.suffix=='.md':
            headings=re.findall(r'^#{1,6}\s+(.+)$',target.read_text(),re.M)
            slugs=[re.sub(r'[^\w\- ]','',h.lower()).replace(' ','-') for h in headings]
            if unquote(frag) not in slugs: errors.append(f'{p.name}: missing heading {url}')
tickets=sorted((w/'issues').glob('*.md'))
assert len(tickets)==7
for n,p in enumerate(tickets,1):
    assert p.name.startswith(f'{n:02}-')
    text=p.read_text()
    for field in ['What to build','Blocked by','Status']:
        if f'**{field}:**' not in text: errors.append(f'{p.name}: missing {field}')
    deps=re.search(r'\*\*Blocked by:\*\* (.+)',text).group(1)
    for dep in re.findall(r'\b0[1-7]\b',deps):
        if int(dep)>=n: errors.append(f'{p.name}: unordered dependency {dep}')
    state=re.search(r'\*\*Status:\*\* (.+)',text).group(1)
    if state!=('ready' if n in (1,2) else 'pending'): errors.append(f'{p.name}: wrong frontier')
    if '- [ ]' not in text: errors.append(f'{p.name}: no acceptance')
before=json.loads(Path('/tmp/agent-context-design-before.json').read_text())
for old,digest in before.items():
    p=Path(old)
    current=w/'materials/2026-10-29-superseded-tickets'/p.name if p.parent.name=='issues' else p
    if not current.exists() or hashlib.sha256(current.read_bytes()).hexdigest()!=digest:
        errors.append(f'Unexpected modification: {p}')
if errors:
    print('\n'.join(errors)); raise SystemExit(1)
print(f'PASS: {len(new)} current documents; {links} local links and anchors; 7 ordered tickets; frontier 01/02.')
print('PASS: original five tickets preserved byte-for-byte; original research and three pre-existing working files unchanged.')
print('Design check only: no production tests, browser tests or model evaluations ran.')
