7	import { SessionLogOffset } from '@deepseek-ai/dsh-session'
8	import { matchesProducerKind } from './context-source.ts'
9	import type { AgentTeamAgentMember, AgentTeamProject } from './types.ts'
10	import { memberMemoryDirectoryPath } from './member-runtime.ts'
