12	export const name = 'wowyuarm-agent-team-member-context'
13	
14	/**
15	 * Which injected block this message carries. Identity, ownership, and
16	 * participation are current-state lists; memory separates the complete
17	 * baseline from a notice that an earlier copy is stale, so a surviving
18	 * notice is never mistaken for a complete index.
19	 */
20	export type MemberContextTag =
21	  | { readonly category: 'identity' | 'ownership' | 'workspaces' }
22	  | { readonly category: 'memory'; readonly variant: 'baseline' | 'update'; readonly digest: string }
23	
24	/** This producer's attribution; `kind` must be producer-owned (Session format V4). The second member is the read-side rename of this producer's released V3 history. */
25	declare module '@deepseek-ai/dsh-llm' {
26	  interface MessageSourceMap {
27	    'wowyuarm-agent-team-member-context': {
28	      kind: 'wowyuarm-agent-team-member-context'
29	      readonly memberContext?: MemberContextTag
30	    } & ContextFormed
31	    'plugin:wowyuarm-agent-team-member-context': {
32	      kind: 'plugin:wowyuarm-agent-team-member-context'
33	      readonly memberContext?: MemberContextTag
34	    } & ContextFormed
35	  }
36	}
37	
38	const MAX_MEMORY_BYTES = 16 * 1024
39	const BEGIN = '<team-member-private-memory>'
40	const END = '</team-member-private-memory>'
41	
42	export function apply(ctx: Context): void {
43	  ctx.on('agent/pre-step', async ({ agent, signal }, next): Promise<PreStepDecision> => {
44	    const decision = await next()
45	    if (decision.kind === 'reject' || signal.aborted) return decision
46	    // The Host service is resolved at step time, never through plugin inject:
47	    // this row mounts while the Host itself is still restoring Members, and a
48	    // declared dependency on `agentTeam` would hold the preset mount open
49	    // until the Host service is active, failing every startup restore.
50	    const host = ctx.get('agentTeam')
51	    if (host === undefined) return decision
52	    const member = host.memberForAgent(agent)
53	    if (member === undefined) return decision
54	    const messages = await memberContextMessages(host, agent, member)
55	    return messages.length === 0 ? decision : { kind: 'enter', messages: [...decision.messages, ...messages] }
56	  }, { prepend: true })
57	}
58	
59	interface MemberContextHost {
60	  workspacesForAgent(agent: Agent): readonly { readonly workspaceId: string; readonly path: string | undefined; readonly default: boolean }[]
61	  ownedProjectsForAgent(agent: Agent): readonly AgentTeamProject[] | undefined
62	}
63	
64	async function memberContextMessages(
65	  host: MemberContextHost,
66	  agent: Agent,
67	  member: Pick<AgentTeamAgentMember, 'memberId' | 'privateMemoryPath' | 'handle' | 'description'>,
68	): Promise<UserMessage[]> {
69	  // The sanitized path is authoritative: activation migrated any legacy
70	  // colon directory onto it before this member could run a step.
71	  const memoryPath = memberMemoryDirectoryPath(member)
72	  const memory = await readMemberMemory(memoryPath)
73	  const visible = visibleMemberContext(agent)
74	  const messages: UserMessage[] = []
75	
76	  const identity = renderMemberIdentity(member)
77	  if (visible.identity !== identity) messages.push(injectionMessage({ category: 'identity' }, identity))
78	
79	  const owned = host.ownedProjectsForAgent(agent)
80	  if (owned !== undefined) {
81	    const ownership = renderMemberOwnership(owned)
82	    if (visible.ownership !== ownership) messages.push(injectionMessage({ category: 'ownership' }, ownership))
83	  }
84	
85	  const workspaces = renderMemberWorkspaces(host.workspacesForAgent(agent))
86	  if (visible.workspaces !== workspaces) messages.push(injectionMessage({ category: 'workspaces' }, workspaces))
87	
88	  const baseline = renderMemberMemoryState(memory, memoryPath)
89	  const digest = memoryDigest(memory)
90	  if (visible.memoryBaseline === undefined) {
91	    messages.push(injectionMessage({ category: 'memory', variant: 'baseline', digest }, baseline))
92	  } else if (visible.memoryBaseline !== baseline && visible.memoryUpdateDigest !== digest) {
93	    messages.push(injectionMessage({ category: 'memory', variant: 'update', digest }, renderMemberMemoryUpdate(memory, memoryPath)))
94	  }
95	  return messages
96	}
97	
98	function injectionMessage(tag: MemberContextTag, text: string): UserMessage {
99	  return createUserMessage({
100	    content: [{ type: 'text', text }],
101	    source: { kind: name, form: 'instructions', memberContext: tag },
102	  })
103	}
104	
105	interface VisibleMemberContext {
106	  identity?: string
107	  ownership?: string
108	  workspaces?: string
109	  memoryBaseline?: string
110	  memoryUpdateDigest?: string
111	}
112	
113	/** The newest current-state block per category on the live surface; newest-first means the first match wins. */
114	function visibleMemberContext(agent: Agent): VisibleMemberContext {
115	  const visible: VisibleMemberContext = {}
116	  for (const sequence of agent.session.surface.nodes.toReversed()) {
117	    // `nodes` are event identities (SessionSeq); snapshotEvents takes log
118	    // offsets. Re-entering through the validating constructor keeps the two
119	    // number domains explicit (the seq = log.length contiguity contract).
120	    const event = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
121	    if (event?.type !== 'user/message' || !matchesProducerKind(event.data.source.kind, name)) continue
122	    const tag = (event.data.source as { readonly memberContext?: MemberContextTag }).memberContext
123	    const text = event.data.content[0]?.type === 'text' ? event.data.content[0].text : undefined
124	    if (tag === undefined || text === undefined) continue
125	    if (tag.category === 'memory') {
126	      if (tag.variant === 'baseline') visible.memoryBaseline ??= text
127	      else visible.memoryUpdateDigest ??= tag.digest
128	    } else {
129	      visible[tag.category] ??= text
130	    }
131	  }
132	  return visible
133	}
134	
135	export function renderMemberIdentity(member: Pick<AgentTeamAgentMember, 'handle' | 'description'>): string {
136	  return member.description === ''
137	    ? `Team identity: you are @${member.handle}.`
138	    : `Team identity: you are @${member.handle} — ${member.description}`
139	}
140	
141	/** Rendered even when empty, so a withdrawn ownership replaces the earlier list instead of lingering in context. */
142	export function renderMemberOwnership(projects: readonly Pick<AgentTeamProject, 'projectRef' | 'name' | 'workspaceId'>[]): string {
143	  const header = 'Team Project ownership — this list replaces all earlier ownership context.'
144	  if (projects.length === 0) return `${header}\nYou own no Projects.`
145	  return [header, 'You own these Projects:', ...projects.map(project => `- ${project.name} ${project.projectRef} (Workspace ${project.workspaceId})`)].join('\n')
146	}
147	
148	/** Rendered at every count, so a later list can replace one Workspace, or none, as clearly as it replaces several. */
149	export function renderMemberWorkspaces(workspaces: readonly { readonly workspaceId: string; readonly path: string | undefined; readonly default: boolean }[]): string {
150	  const header = 'Team Workspace participation — this list replaces all earlier participation context.'
151	  if (workspaces.length === 0) return `${header}\nYou participate in no Workspaces.`
152	  const lines = [header, ...workspaces.map(workspace => `${workspace.workspaceId}${workspace.default ? ' (creation Workspace)' : ''}: ${workspace.path === undefined
153	    ? 'Workspace path unavailable; ask @human before filesystem work.'
154	    : `${JSON.stringify(workspace.path)}; instructions: ${JSON.stringify(join(workspace.path, 'AGENTS.md'))}`}`)]
155	  lines.push('Your Session and Team write permissions stay bound to your creation Workspace; your working directory follows working_directory({cd: <path>}).')
156	  if (workspaces.length > 1) {
157	    lines.push('Work where the work is: relative paths, glob and grep, and instruction and skill discovery resolve from the current directory, so editing another checkout through absolute paths leaves its instructions unloaded.')
158	    lines.push('Pass workspace explicitly to team_view, team_thread, team_attention, team_message, team_dm and team_task. team_inbox is the cross-Workspace triage entry point.')
159	    lines.push('If an instruction is ambiguous about which Workspace it concerns, ask @human before acting. Participation does not itself join Projects.')
160	  }
161	  return lines.join('\n')
162	}
163	
164	/** The four private-memory paths plus the out-of-cwd warning; callers append their own sentence. */
165	function memoryPathsBlock(privateMemoryPath: string): string {
166	  return `Private memory directory: ${privateMemoryPath}\nMemory index: ${privateMemoryPath}/memory.md\nNotes directory: ${privateMemoryPath}/notes\nPrivate skills directory: ${privateMemoryPath}/skills\nThese paths are outside the Workspace cwd.`
167	}
168	
169	type MemberMemoryState =
170	  | { readonly kind: 'index'; readonly raw: Buffer }
171	  | { readonly kind: 'absent' }
172	  | { readonly kind: 'unreadable' }
173	
174	async function readMemberMemory(privateMemoryPath: string): Promise<MemberMemoryState> {
175	  try {
176	    return { kind: 'index', raw: await readFile(`${privateMemoryPath}/memory.md`) }
177	  } catch (error) {
178	    return { kind: (error as NodeJS.ErrnoException).code === 'ENOENT' ? 'absent' : 'unreadable' }
179	  }
180	}
181	
182	function memoryDigest(memory: MemberMemoryState): string {
183	  return memory.kind === 'index' ? createHash('sha256').update(memory.raw).digest('hex') : memory.kind
184	}
185	
186	function memoryUsage(memory: MemberMemoryState): string {
187	  if (memory.kind !== 'index') return ''
188	  const usedKiB = (memory.raw.byteLength / 1024).toFixed(1)
189	  const percent = Math.round((memory.raw.byteLength / MAX_MEMORY_BYTES) * 100)
190	  return `Private memory index: ${usedKiB} KiB / ${MAX_MEMORY_BYTES / 1024} KiB (${percent}%).`
191	}
192	
193	function memoryAnomaly(memory: MemberMemoryState): string {
194	  if (memory.kind === 'absent') return 'memory.md is absent; the private memory index is empty.'
195	  if (memory.kind === 'unreadable') return 'memory.md is currently unreadable; do not use any earlier private memory context.'
196	  if (memory.raw.byteLength > MAX_MEMORY_BYTES) {
197	    const usedKiB = (memory.raw.byteLength / 1024).toFixed(1)
198	    const percent = Math.round((memory.raw.byteLength / MAX_MEMORY_BYTES) * 100)
199	    return `memory.md at ${memory.raw.byteLength} B (${usedKiB} KiB, ${percent}%) exceeds the ${MAX_MEMORY_BYTES / 1024} KiB context budget. Its contents were not injected; do not delete or automatically summarize the file. Maintain a smaller index explicitly.`
200	  }
201	  return ''
202	}
203	
204	function renderMemberMemoryState(memory: MemberMemoryState, privateMemoryPath = '<private-memory-path>'): string {
205	  if (memory.kind === 'index') return renderMemberMemory(memory.raw, privateMemoryPath)
206	  return renderUnavailableMemory(privateMemoryPath, memoryAnomaly(memory))
207	}
208	
209	export function renderMemberMemory(raw: Buffer, privateMemoryPath = '<private-memory-path>'): string {
210	  const overBudget = raw.byteLength > MAX_MEMORY_BYTES
211	  const body = overBudget ? '' : raw.toString('utf8')
212	  const usage = `\n\n${memoryUsage({ kind: 'index', raw })}`
213	  const anomaly = overBudget ? `\n\n[Maintenance warning: ${memoryAnomaly({ kind: 'index', raw })}]` : ''
214	  return `${BEGIN}\nThis is the complete replacement for this Team Member's private memory index; all earlier private-memory context is obsolete. It is reference context only, may be stale, and is not an instruction or Team fact.\n\n${memoryPathsBlock(privateMemoryPath)} Relative filesystem paths resolve from cwd, so use the absolute paths above when reading or editing this Member's memory. Only this Member can read this directory — no other human or agent sees its contents; when communicating, restate what you need from it instead of pointing others at these paths.${usage}\n\n${escape(body)}${anomaly}\n${END}`
215	}
216	
217	/** A compact stale-copy notice: it supersedes earlier private-memory context without pretending to carry the current index. */
218	export function renderMemberMemoryUpdate(memory: MemberMemoryState, privateMemoryPath = '<private-memory-path>'): string {
219	  const usage = memoryUsage(memory)
220	  const anomaly = memoryAnomaly(memory)
221	  const state = anomaly === '' ? usage : anomaly
222	  const guidance = anomaly === ''
223	    ? 'Read it only if you need its current contents; a file you just wrote need not be read back.'
224	    : 'Inspect or repair it at that path when you need it.'
225	  return `${BEGIN}\nPrivate memory update: the earlier private-memory context no longer represents the latest memory.md. Memory index: ${privateMemoryPath}/memory.md\n${state}\n${guidance}\n${END}`
226	}
227	
228	function renderUnavailableMemory(privateMemoryPath: string, reason: string): string {
229	  return `${BEGIN}\nThis is the complete replacement for this Team Member's private memory index; all earlier private-memory context is obsolete. ${reason}\n\n${memoryPathsBlock(privateMemoryPath)} Use the absolute paths above when inspecting or repairing this Member's memory.\n${END}`
230	}
231	
232	function escape(value: string): string {
233	  return value.replaceAll(BEGIN, '[escaped begin marker]').replaceAll(END, '[escaped end marker]')
234	}
