1	// One-off corpus measurement: result sizes per tool/action, notice and member-context injection sizes,
2	// and what the model does right after unread_required / stale_revision.
3	import { readdirSync } from 'node:fs'
4	import { join } from 'node:path'
5	import { spawnSync } from 'node:child_process'
6	const ROOT = `${process.env.HOME}/.dsh/sessions`
7	function* walk(d) { for (const e of readdirSync(d, { withFileTypes: true })) { const p = join(d, e.name); if (e.isDirectory()) yield* walk(p); else if (e.name.endsWith('.jsonl.zstd')) yield p } }
8	const sizes = new Map(), injections = new Map(), after = new Map()
9	const add = (m, k, v) => { if (!m.has(k)) m.set(k, []); m.get(k).push(v) }
10	let files = 0
11	for (const f of walk(ROOT)) {
12	  files++
13	  const r = spawnSync('zstd', ['-dc', f], { maxBuffer: 1024 * 1024 * 1024 })
14	  if (r.status !== 0) continue
15	  const pending = new Map(); const seq = []  // per-file ordered team calls with outcome
16	  for (const line of r.stdout.toString('utf8').split('\n')) {
17	    if (!line) continue
18	    let ev; try { ev = JSON.parse(line) } catch { continue }
19	    const d = ev.data; if (!d) continue
20	    if (ev.type === 'tool/call' && typeof d.name === 'string' && d.name.startsWith('team_')) {
21	      let a = {}; try { a = JSON.parse(d.arguments) } catch {}
22	      pending.set(d.callId, { tool: d.name, action: a.action ?? '-', args: a })
23	    } else if (ev.type === 'tool/result' && d.message?.toolCallId && pending.has(d.message.toolCallId)) {
24	      const c = pending.get(d.message.toolCallId); pending.delete(d.message.toolCallId)
25	      const text = (d.message.content || []).filter(x => x?.type === 'text').map(x => x.text).join('\n')
26	      const cls = d.message.isError ? 'thrown' : /^Not committed — (unread_required|main_unread_required)/.test(text) ? RegExp.$1 : /^Not committed — .*stale_revision/.test(text) ? 'stale_revision' : /^Not committed/.test(text) ? 'reject-other' : 'ok'
27	      const scope = c.args.projectRef && c.tool === 'team_thread' ? ':main' : ''
28	      add(sizes, `${c.tool} ${c.action}${scope} ${cls === 'ok' ? '' : cls}`.trim(), text.length)
29	      seq.push({ ...c, cls, base: c.args.baseRevision, text })
30	    } else if (ev.type === 'user/message' && d.source && typeof d.source.kind === 'string') {
31	      const k = d.source.kind
32	      if (!/agent-team/.test(k)) continue
33	      const text = (d.content || []).filter(x => x?.type === 'text').map(x => x.text).join('\n')
34	      const label = /member-context/.test(k) ? 'member-context block' : /time-context/.test(k) ? 'time-context' : `${k.replace(/.*agent-team/, 'team')} ${d.source.form ?? ''} ${(d.source.summary ?? '').slice(0, 30)}`
35	      add(injections, label, text.length)
36	    }
37	  }
38	  for (let i = 0; i < seq.length; i++) {
39	    const s = seq[i]; if (!['unread_required', 'stale_revision'].includes(s.cls)) continue
40	    const n = seq[i + 1]
41	    let next = 'none'
42	    if (n) {
43	      if (n.tool === 'team_thread' && n.action === 'read') next = 'read'
44	      else if (n.tool === s.tool && n.action === s.action) {
45	        const m = /baseRevision: (\d+)/.exec(s.text); const offered = m ? Number(m[1]) : undefined
46	        next = `same-write retry (${n.base === offered ? 'with offered token' : 'other token'}) -> ${n.cls}`
47	      } else next = `${n.tool} ${n.action}`
48	    }
49	    add(after, `${s.cls}: ${next}`, 1)
50	  }
51	}
52	const q = (a, p) => { const s = [...a].sort((x, y) => x - y); return s[Math.min(s.length - 1, Math.floor(p * s.length))] }
53	console.log('files', files)
54	console.log('\n== tool result chars (n, p50, p90, max, total) ==')
55	for (const [k, v] of [...sizes].sort((a, b) => b[1].reduce((x, y) => x + y, 0) - a[1].reduce((x, y) => x + y, 0))) if (v.length >= 3) console.log(k.padEnd(48), v.length, q(v, .5), q(v, .9), Math.max(...v), v.reduce((x, y) => x + y, 0))
56	console.log('\n== injected team user messages (n, p50, p90, max, total) ==')
57	for (const [k, v] of [...injections].sort((a, b) => b[1].length - a[1].length)) console.log(k.padEnd(60), v.length, q(v, .5), q(v, .9), Math.max(...v), v.reduce((x, y) => x + y, 0))
58	console.log('\n== next call after a deferred write ==')
59	for (const [k, v] of [...after].sort((a, b) => b[1].length - a[1].length)) console.log(String(v.length).padStart(5), k)
