177	async function runScenario(seed: ScenarioSeed, tag = ''): Promise<CallLog[]> {
178	  const { boot, agent, tools, seeded } = await bootScenario(seed)
179	  const logs: CallLog[] = []
180	  const toolSpecs = [...tools.values()].map((tool) => ({
181	    type: 'function',
182	    function: { name: tool.name, description: tool.description, parameters: tool.parameters as Record<string, unknown> },
183	  }))
184	  const messages: unknown[] = [
185	    { role: 'system', content: systemPrompt(seeded) },
186	    { role: 'user', content: seed.task },
187	  ]
188	  try {
189	    for (let turn = 1; turn <= MAX_TURNS; turn++) {
190	      const message = await chat(messages, toolSpecs) as { content?: string; tool_calls?: Array<{ id: string; function: { name: string; arguments: string } }> }
191	      messages.push(message)
192	      const calls = message.tool_calls ?? []
193	      if (calls.length === 0) break
194	      for (const call of calls) {
195	        const tool = tools.get(call.function.name)
196	        let args: Record<string, unknown> = {}
197	        try { args = JSON.parse(call.function.arguments || '{}') } catch { /* keep empty */ }
198	        const startedAt = Date.now()
199	        let kind: CallLog['kind'] = 'ok'
200	        let reason = ''
201	        let text = ''
202	        if (tool === undefined) {
203	          kind = 'thrown'; reason = 'unknown_tool'; text = `no such tool: ${call.function.name}`
204	        } else {
205	          try {
206	            const value = await tool.execute(args, { agent, callId: call.id, signal: new AbortController().signal } as never)
207	            const blocks = tool.output.render(args as never, value as never) as Array<{ type: string; text?: string }>
208	            text = blocks.map((b) => (b.type === 'text' ? b.text : '')).join('\n')
209	            const classified = classifyText(text)
210	            kind = classified.kind; reason = classified.reason
211	          } catch (error) {
212	            kind = 'thrown'; reason = (error as Error).message.slice(0, 120); text = reason
213	          }
214	        }
215	        const schemaProps = new Set(Object.keys(((tool?.parameters as { properties?: Record<string, unknown> } | undefined)?.properties) ?? {}))
216	        const blankFills = Object.entries(args).filter(([, v]) => v === '' || v === 0 || v === false).map(([k]) => k)
217	        const strayParams = Object.keys(args).filter((k) => k !== 'action' && !schemaProps.has(k))
218	        logs.push({ scenario: seed.name, turn, tool: call.function.name, action: String(args.action ?? ''), args, kind, reason, text: text.slice(0, 400), blankFills, strayParams, ms: Date.now() - startedAt })
219	        messages.push({ role: 'tool', tool_call_id: call.id, content: text || '(empty result)' })
220	      }
221	    }
222	  } finally {
223	    writeFileSync(join(OUT_DIR, `transcript-${seed.name}${tag}.json`), JSON.stringify({ scenario: seed.name, round: tag, task: seed.task, seeded, messages, calls: logs }, null, 2))
224	    await (boot.ctx as { dispose?: () => Promise<void> }).dispose?.()
225	  }
226	  return logs
227	}

